#!/usr/bin/env python3
"""
CAMPANHAS — NOVO CRITÉRIO "FAIXAS DE VALOR" (quem atingir ganha, sem limite de ganhadores).

COMO FUNCIONA
  • Ao criar a campanha, escolha o critério "🎚️ Faixas de valor". Para CADA time (OAO, R1 ou os dois) você define quantas faixas quiser: "quem atingir R$ X ganha o prêmio P".
    Exemplo (o seu): R$ 1.000 → R$ 100 · R$ 2.000 → R$ 200 · R$ 3.000 → R$ 300.
  • NÃO há limite de ganhadores: quem atingir, ganha — seja 1 pessoa ou todas. Quem passar de mais de uma faixa ganha SÓ o prêmio da faixa mais alta (não soma).
  • Conta a receita das vendas do período (a mesma atribuição das outras campanhas: self checkout transferido para closer, venda de embaixador com co-closer, etc.).
  • Durante a campanha: quem atinge uma faixa recebe o aviso na hora ("você atingiu R$ X e ganhou: P") — uma vez por faixa; quem sobe de faixa recebe o aviso da nova, e o prêmio
    registrado acompanha. Ao fechar (fim do último dia): aviso pessoal de cada premiado + resultado para todos + aviso ao criador. A entrega do prêmio é marcada em Campanhas → Ganhadores.
  • Os outros critérios NÃO mudam.
  • BÔNUS (correção): na atribuição de vendas das campanhas, o co_closer_id é id de PERFIL; antes, um co-closer SEM hubspot cadastrado não contava. Agora conta.

ANTES DE USAR: rode no Supabase o arquivo migration-faixas.sql (só ajusta a restrição do campo "criterion" para aceitar o valor novo; é seguro rodar mais de uma vez).

Arquivos NOVOS (4): lib/campaigns/tiers.ts · lib/campaigns/tiers-server.ts · components/campaigns/TierEditor.tsx · components/campaigns/TierViews.tsx
Arquivos ALTERADOS: lib/campaigns/{types,engine,server,api,handlers}.ts · components/campaigns/{CampaignBuilder,CampaignPreview}.tsx · app/(platform)/admin/campanhas/CampanhasClient.tsx
SEGURANÇA: antes de gravar, guarda uma cópia exata de cada arquivo alterado (<arquivo>.bak-faixas); --desfazer restaura as cópias e remove os arquivos novos. Tudo-ou-nada por arquivo:
se UM trecho não for reconhecido, o arquivo NÃO é tocado e o motivo aparece. Rodar de novo não duplica. Preserva CRLF/LF e BOM.

Uso (na RAIZ do projeto):   python aplicar-faixas-campanha.py .   |  --dry-run (só mostra)  |  --desfazer
"""
import os, re, sys

NOVOS = {
  'lib/campaigns/tiers.ts': 'import { fmtBRL } from \'@/lib/telao/format\'\nimport { CampaignDraft, Team, TEAMS, Tier } from \'./types\'\n\n// ══ Critério "Faixas de valor" (tier_revenue) ═══════════════════════════════════════════════════════════\n//  Cada time tem N faixas: "quem atingir R$ X ganha o prêmio P". NÃO há limite de ganhadores: quem atinge, ganha — seja 1 ou todos.\n//  Quem atinge mais de uma faixa ganha SÓ o prêmio da mais alta (não soma). Conta a receita do período (mesma atribuição das outras campanhas).\n//  Este arquivo é puro (sem banco e sem tela) e NÃO importa o engine (o engine é que importa este).\n\nexport const isTierCriterion = (c: unknown): boolean => c === \'tier_revenue\'\nconst EPS = 1e-6\nconst round2 = (n: number) => Math.round(n * 100) / 100\nconst firstWord = (s: string) => (s.trim().split(/\\s+/)[0] ?? s)\n\nexport interface TierRow { target: number; prize: string }\n/** Só as faixas válidas (valor > 0 e prêmio preenchido), em ordem crescente de valor. */\nexport function sortedTiers(tiers: Tier[] | undefined | null): TierRow[] {\n  return (tiers ?? []).filter(t => typeof t?.target === \'number\' && t.target > 0 && String(t.prize ?? \'\').trim()).map(t => ({ target: round2(t.target as number), prize: String(t.prize).trim() })).sort((a, b) => a.target - b.target)\n}\n/** Lê as faixas vindas da tela (nunca confia no que chega). Mantém faixas incompletas (rascunho). */\nexport function cleanTiers(raw: unknown, max = 10): Tier[] {\n  if (!Array.isArray(raw)) return []\n  return raw.slice(0, max).map((x: any) => { const n = x?.target === null || x?.target === \'\' || x?.target === undefined ? null : Number(x.target); return { target: n !== null && Number.isFinite(n) && n > 0 ? round2(n) : null, prize: String(x?.prize ?? \'\').slice(0, 120) } })\n}\n/** Índice (na lista ORDENADA) da faixa mais alta cujo valor foi atingido; -1 se nenhuma. */\nexport function tierIndexFor(sorted: TierRow[], revenue: number): number {\n  let idx = -1\n  for (let i = 0; i < sorted.length; i++) if (revenue + EPS >= sorted[i].target) idx = i\n  return idx\n}\nexport interface TierStanding { tier: number | null; tierTarget: number | null; tierPrize: string | null; nextTarget: number | null; nextPrize: string | null; progress: number; tierHits: (string | null)[] }\n/** Situação de UMA pessoa: faixa atual, próxima, e QUANDO bateu cada faixa (pelas vendas, em ordem de horário). */\nexport function tierStanding(tiers: Tier[] | undefined | null, sales: { at: string; value: number }[]): TierStanding {\n  const s = sortedTiers(tiers), total = sales.reduce((a, c) => a + c.value, 0), idx = tierIndexFor(s, total)\n  const hits: (string | null)[] = s.map(() => null); let acc = 0\n  for (const c of sales) { acc += c.value; s.forEach((t, i) => { if (hits[i] === null && acc + EPS >= t.target) hits[i] = c.at }) }\n  const next = s[idx + 1] ?? null\n  return {\n    tier: idx >= 0 ? idx : null, tierTarget: idx >= 0 ? s[idx].target : null, tierPrize: idx >= 0 ? s[idx].prize : null,\n    nextTarget: next ? next.target : null, nextPrize: next ? next.prize : null,\n    progress: s.length === 0 ? 0 : next ? Math.min(total / next.target, 1) : 1, tierHits: hits,\n  }\n}\nexport const tiersValid = (tiers: Tier[] | undefined | null): boolean => {\n  const l = tiers ?? []\n  if (l.length < 1 || l.length > 10) return false\n  const ts = l.map(t => t.target)\n  return l.every(t => typeof t.target === \'number\' && t.target > 0 && String(t.prize ?? \'\').trim().length > 0 && String(t.prize).trim().length <= 120) && new Set(ts).size === ts.length\n}\n\n/** Mensagens de erro (a tela e a API usam a MESMA). strict=false (rascunho): só confere o que já foi preenchido. */\nexport function validateTiers(d: Pick<CampaignDraft, \'teams\'>, teams: Team[], strict: boolean): string[] {\n  const e: string[] = []\n  for (const t of teams) {\n    const l = d.teams[t]?.tiers ?? []\n    if (strict && l.length === 0) { e.push(`Time ${t}: adicione pelo menos uma faixa (valor e prêmio).`); continue }\n    if (l.length > 10) e.push(`Time ${t}: no máximo 10 faixas.`)\n    const seen = new Set<number>()\n    l.forEach((x, i) => {\n      const n = i + 1\n      if (x.target !== null && x.target !== undefined && !(typeof x.target === \'number\' && x.target > 0)) e.push(`Time ${t}, faixa ${n}: o valor precisa ser maior que zero.`)\n      else if (strict && !(typeof x.target === \'number\' && x.target > 0)) e.push(`Time ${t}, faixa ${n}: informe o valor (R$).`)\n      else if (typeof x.target === \'number\') { if (seen.has(round2(x.target))) e.push(`Time ${t}: há duas faixas com o mesmo valor (${fmtBRL(x.target)}).`); seen.add(round2(x.target)) }\n      const p = String(x.prize ?? \'\').trim()\n      if (strict && !p) e.push(`Time ${t}, faixa ${n}: informe o prêmio.`)\n      else if (p.length > 120) e.push(`Time ${t}, faixa ${n}: o prêmio pode ter até 120 caracteres.`)\n    })\n  }\n  return e\n}\nexport const tierTargetsKey = (tiers: Tier[] | undefined | null): string => sortedTiers(tiers).map(t => t.target).join(\',\')\n\n// ── textos ──────────────────────────────────────────────────────────────────\nconst teamsOf = (d: Pick<CampaignDraft, \'teams\'>): Team[] => TEAMS.filter(t => d.teams[t])\n/** "R$ 1.000 → R$ 100 · R$ 2.000 → R$ 200" (se os dois times têm as mesmas faixas, não repete por time). */\nexport function tiersText(d: Pick<CampaignDraft, \'teams\'>): string {\n  const ts = teamsOf(d), lines = ts.map(t => sortedTiers(d.teams[t]!.tiers).map(x => `${fmtBRL(x.target)} → ${x.prize}`).join(\' · \'))\n  return lines.length > 1 && lines.every(l => l === lines[0]) ? lines[0] : ts.map((t, i) => (ts.length > 1 ? `${t}: ${lines[i]}` : lines[i])).join(\' | \')\n}\nexport function howToWinTiers(d: Pick<CampaignDraft, \'teams\'>, period: string): string {\n  return `Todos que atingirem uma das faixas de vendas ${period} ganham o prêmio da faixa mais alta alcançada (sem limite de ganhadores).`\n}\nexport function tierHitMessage(campaignName: string, w: { metric: number; tierTarget: number; tierPrize: string; nextTarget: number | null; nextPrize: string | null }): { title: string; body: string } {\n  return {\n    title: `🎯 Você atingiu ${fmtBRL(w.tierTarget)} e ganhou: ${w.tierPrize}!`,\n    body: `Campanha ${campaignName.trim()}: você já soma ${fmtBRL(w.metric)}. ${w.nextTarget !== null ? `Faltam ${fmtBRL(Math.max(w.nextTarget - w.metric, 0))} para a próxima faixa (${fmtBRL(w.nextTarget)}: ${w.nextPrize}).` : \'Você está na faixa mais alta!\'}`,\n  }\n}\nexport function finishMessagesTiers(d: CampaignDraft, results: { team: Team; winners: { name: string; metric: number; prize?: string | null }[] }[]) {\n  const name = d.name.trim()\n  const line = (t: { team: Team; winners: { name: string; metric: number; prize?: string | null }[] }) => {\n    if (t.winners.length === 0) return `${t.team}: sem ganhadores`\n    const by = new Map<string, string[]>(); for (const w of [...t.winners].sort((a, b) => b.metric - a.metric)) { const k = w.prize ?? \'\'; (by.get(k) ?? by.set(k, []).get(k)!).push(firstWord(w.name)) }\n    return `${t.team}: ${t.winners.length} ${t.winners.length === 1 ? \'premiado\' : \'premiados\'} — ${[...by].map(([p, ns]) => `${p}: ${ns.join(\', \')}`).join(\' · \')}`\n  }\n  const lines = results.map(line).join(\' · \')\n  return {\n    personal: (w: { team: Team; metric: number; prize?: string | null }, _position: number) => {\n      const s = sortedTiers(d.teams[w.team]?.tiers), i = tierIndexFor(s, w.metric)\n      return { title: `🏆 Você ganhou: ${w.prize || (i >= 0 ? s[i].prize : \'\')}!`, body: `Campanha ${name}: você atingiu ${fmtBRL(w.metric)}${i >= 0 ? ` e fechou na faixa de ${fmtBRL(s[i].target)}` : \'\'}. Parabéns!` }\n    },\n    everyone: { title: `🏁 Resultado: ${name}`, body: `${lines}.` },\n    creator: { title: `✅ Campanha encerrada: ${name}`, body: `${lines}. Marque a entrega do prêmio em Administração → Campanhas.` },\n  }\n}\n\n/** Popup dos vencedores (SÓ nome e prêmio — nunca quanto vendeu): os premiados de cada time, do maior prêmio (faixa) para o menor. */\nexport function tierTeamsView(d: Pick<CampaignDraft, \'teams\'>, allowed: Team[], winners: any[], userId: string, closed: boolean) {\n  return allowed.map(team => {\n    const s = sortedTiers(d.teams[team]?.tiers), mine = winners.filter(w => w.team === team)\n      .sort((a, b) => Number(b.metric_value ?? 0) - Number(a.metric_value ?? 0) || String(a.user_name).localeCompare(String(b.user_name)))\n    return {\n      team, tiers: s,\n      positions: mine.map((w, i) => ({ position: i + 1, prize: w.prize || null, winner: { name: w.user_name as string, me: w.user_id === userId }, state: \'winner\' })),\n      ...(mine.length === 0 ? { empty: closed ? \'Ninguém atingiu uma faixa.\' : \'Ainda ninguém atingiu uma faixa.\' } : {}),\n    }\n  })\n}\n',
  'lib/campaigns/tiers-server.ts': 'import { tierHitMessage, sortedTiers, tierIndexFor } from \'./tiers\'\n\n// ══ Faixas de valor — parte do SERVIDOR (apuração durante a campanha e fechamento) ═══════════════════════\n// Tudo idempotente: rodar a rotina várias vezes dá o mesmo resultado. Os ganhadores ficam em campaign_winners (1 linha por pessoa e time),\n// com posição ESTÁVEL (ordem em que bateram a 1ª faixa: quem já está registrado não muda de posição). O prêmio acompanha a faixa mais alta atingida.\n\ntype Send = (title: string, body: string, kind: \'campanha\' | \'vitoria\', to: string[], event_key: string) => Promise<void>\n\n/** Durante a campanha (e na última apuração, ao fechar): registra quem atingiu faixa, atualiza o prêmio de quem subiu, tira quem deixou de atingir e avisa. */\nexport async function tickTierWinners(o: { admin: any; c: any; d: any; ev: any; participants: any[]; send: Send; claim: (key: string) => Promise<boolean>; sum: { winners: number } }) {\n  const { admin, c, d, ev, send, claim, sum } = o\n  const { data: cur } = await admin.from(\'campaign_winners\').select(\'*\').eq(\'campaign_id\', c.id)\n  const rows = (cur ?? []) as any[]\n  for (const t of ev.teams) {\n    const mine = rows.filter(r => r.team === t.team), byUser = new Map<string, any>(mine.map(r => [r.user_id, r]))\n    let nextPos = Math.max(0, ...mine.map(r => Number(r.position))) + 1\n    const qualified = (t.winners as any[]).slice().sort((a, b) => (a.reachedAt ?? \'\').localeCompare(b.reachedAt ?? \'\') || a.userId.localeCompare(b.userId))\n    for (const w of qualified) {\n      const prize = w.tierPrize ?? \'\', ex = byUser.get(w.userId)\n      if (!ex) {\n        const { error } = await admin.from(\'campaign_winners\').insert({ campaign_id: c.id, team: t.team, position: nextPos++, user_id: w.userId, user_name: w.name, metric_value: w.metric, reached_at: w.reachedAt, prize })\n        if (!error) sum.winners++\n      } else if ((ex.prize ?? \'\') !== prize || Number(ex.metric_value ?? 0) !== w.metric || ex.user_name !== w.name) {\n        await admin.from(\'campaign_winners\').update({ prize, metric_value: w.metric, user_name: w.name, reached_at: w.reachedAt ?? ex.reached_at }).eq(\'id\', ex.id)\n      }\n      // aviso: só da faixa MAIS ALTA atingida e uma vez por faixa (as de baixo ficam "marcadas" sem avisar, pra não avisar depois)\n      for (let k = 0; k <= (w.tier ?? -1); k++) {\n        if (!(await claim(`tier:${t.team}:${w.userId}:${k}`))) continue\n        if (k === w.tier) { const m = tierHitMessage(d.name, { metric: w.metric, tierTarget: w.tierTarget, tierPrize: w.tierPrize, nextTarget: w.nextTarget, nextPrize: w.nextPrize }); await send(m.title, m.body, \'vitoria\', [w.userId], `tier:personal:${t.team}:${w.userId}:${k}`) }\n      }\n    }\n    // quem deixou de atingir (ex.: venda estornada): sai, a menos que o prêmio já tenha sido entregue\n    const still = new Set(qualified.map((w: any) => w.userId))\n    for (const r of mine) if (!still.has(r.user_id) && !r.delivered_at) await admin.from(\'campaign_winners\').delete().eq(\'id\', r.id)\n  }\n}\n\n/** Ao fechar: o aviso pessoal "Você ganhou: …" de cada premiado (mesma chave dos outros critérios: finish:personal:TIME:POSIÇÃO).\n *  SÓ de quem atinge a faixa no fim: uma linha mantida porque o prêmio já tinha sido entregue (e a venda foi estornada depois) fica para a gestão decidir, sem aviso de vitória. */\nexport async function finishTierWinners(o: { admin: any; c: any; d: any; ev: any; send: Send; msgs: any; sum: { winners: number } }) {\n  const { admin, c, ev, send, msgs } = o\n  const still = new Set<string>(); for (const t of ev.teams) for (const w of t.winners) still.add(w.userId)\n  const { data } = await admin.from(\'campaign_winners\').select(\'*\').eq(\'campaign_id\', c.id)\n  for (const w of ((data ?? []) as any[]).filter(r => still.has(r.user_id)).sort((a, b) => a.team.localeCompare(b.team) || a.position - b.position)) {\n    const m = msgs.personal({ team: w.team, metric: Number(w.metric_value ?? 0), prize: w.prize ?? null }, w.position)\n    await send(m.title, m.body, \'vitoria\', [w.user_id], `finish:personal:${w.team}:${w.position}`)\n  }\n}\n\n/** Editou o texto/valor das faixas: o prêmio de quem já está registrado acompanha (antes de reescrever os avisos já enviados). */\nexport async function refreshTierWinnerPrizes(admin: any, row: any) {\n  const { data } = await admin.from(\'campaign_winners\').select(\'*\').eq(\'campaign_id\', row.id)\n  for (const w of (data ?? []) as any[]) {\n    const s = sortedTiers(row.teams?.[w.team]?.tiers), i = tierIndexFor(s, Number(w.metric_value ?? 0)), prize = i >= 0 ? s[i].prize : null\n    if (prize && prize !== w.prize) await admin.from(\'campaign_winners\').update({ prize }).eq(\'id\', w.id)\n  }\n}\n',
  'components/campaigns/TierEditor.tsx': '\'use client\'\nimport { Copy, Plus, X } from \'lucide-react\'\nimport { Team, Tier } from \'@/lib/campaigns/types\'\nimport { Btn } from \'./ui\'\n\n// ══ Editor das faixas de valor de UM time: cada linha é "quem atingir R$ X ganha o prêmio P" ═══════════\n// Sem limite de ganhadores; quem passa de mais de uma faixa ganha SÓ a mais alta. A ordem digitada não importa (o sistema ordena por valor);\n// as linhas NUNCA mudam de lugar sozinhas (isso fazia o prêmio ir para a linha errada ao dar Tab) — só pelo botão "Ordenar por valor".\nconst byTarget = (a: Tier, b: Tier) => (a.target ?? Infinity) - (b.target ?? Infinity)\n\nexport function TierEditor({ team, tiers, onChange, copyFrom }: { team: Team; tiers: Tier[]; onChange: (t: Tier[]) => void; copyFrom?: { team: Team; tiers: Tier[] } | null }) {\n  const set = (i: number, p: Partial<Tier>) => onChange(tiers.map((t, k) => (k === i ? { ...t, ...p } : t)))\n  const unsorted = tiers.length > 1 && tiers.every(t => t.target !== null) && tiers.some((t, k) => k > 0 && (t.target as number) < (tiers[k - 1].target as number))\n  const dup = (i: number) => tiers[i].target !== null && tiers.some((t, k) => k !== i && t.target === tiers[i].target)\n  return (\n    <div data-tier-editor={team} style={{ display: \'flex\', flexDirection: \'column\', gap: 10 }}>\n      <div style={{ display: \'flex\', alignItems: \'center\', gap: 10 }}>\n        <span style={{ flex: 1, fontSize: 12, fontWeight: 800, letterSpacing: \'.04em\', color: \'var(--foreground)\' }}>Faixas de valor <span style={{ fontWeight: 500, color: \'var(--muted-foreground)\' }}>· {tiers.length} {tiers.length === 1 ? \'faixa\' : \'faixas\'}</span></span>\n        {copyFrom && copyFrom.tiers.length > 0 && <Btn size="sm" data-tier-copy={`${copyFrom.team}-${team}`} onClick={() => onChange(copyFrom.tiers.map(t => ({ ...t })))}><Copy size={13} />Copiar do {copyFrom.team}</Btn>}\n      </div>\n      {tiers.map((t, i) => (\n        <div key={i} data-tier-row={`${team}-${i}`} style={{ display: \'grid\', gridTemplateColumns: \'28px minmax(110px,1fr) minmax(130px,1.4fr) 36px\', gap: 8, alignItems: \'center\' }}>\n          <span style={{ fontSize: 12, fontWeight: 800, color: \'var(--muted-foreground)\', textAlign: \'center\' }}>{i + 1}ª</span>\n          <input className="cp-field" data-tier-target={`${team}-${i}`} type="number" min={1} step="0.01" inputMode="decimal" aria-label={`Valor da faixa ${i + 1} (R$)`} placeholder="R$ valor" value={t.target ?? \'\'}\n            style={dup(i) ? { borderColor: \'#ef4444\' } : undefined}\n            onChange={e => set(i, { target: e.target.value === \'\' ? null : Number(e.target.value) })} />\n          <input className="cp-field" data-tier-prize={`${team}-${i}`} aria-label={`Prêmio da faixa ${i + 1}`} placeholder="Prêmio (ex.: R$ 100)" maxLength={120} value={t.prize} onChange={e => set(i, { prize: e.target.value })} />\n          <button type="button" className="cp-ib" data-tier-del={`${team}-${i}`} aria-label={`Remover faixa ${i + 1}`} disabled={tiers.length <= 1} onClick={() => onChange(tiers.filter((_, k) => k !== i))} style={{ width: 36, height: 36 }}><X size={14} /></button>\n        </div>\n      ))}\n      <div style={{ display: \'flex\', alignItems: \'center\', gap: 10, flexWrap: \'wrap\' }}>\n        <Btn size="sm" data-tier-add={team} disabled={tiers.length >= 10} onClick={() => onChange([...tiers, { target: null, prize: \'\' }])}><Plus size={13} />Adicionar faixa</Btn>\n        {unsorted && <Btn size="sm" data-tier-sort={team} onClick={() => onChange([...tiers].sort(byTarget))}>Ordenar por valor</Btn>}\n        <span style={{ fontSize: 11.5, lineHeight: 1.45, color: \'var(--muted-foreground)\', flex: 1, minWidth: 200 }}>Quem atingir uma faixa ganha o prêmio dela; quem passar de mais de uma ganha só a mais alta. Sem limite de ganhadores.</span>\n      </div>\n    </div>\n  )\n}\n',
  'components/campaigns/TierViews.tsx': '\'use client\'\nimport { Team, Tier } from \'@/lib/campaigns/types\'\nimport { sortedTiers } from \'@/lib/campaigns/tiers\'\nimport { fmtBRL } from \'@/lib/telao/format\'\n\n/** Bloco do time na prévia/cards quando o critério é "Faixas de valor": lista valor → prêmio (em ordem crescente). */\nexport function TierTeamBlock({ team, tiers }: { team: Team; tiers: Tier[] }) {\n  const s = sortedTiers(tiers)\n  return (\n    <div data-team-block={team} data-tier-block style={{ flex: 1, minWidth: 170, padding: \'10px 12px\', borderRadius: 14, background: \'var(--secondary)\', border: \'1px solid var(--border)\' }}>\n      <div style={{ display: \'flex\', alignItems: \'center\', justifyContent: \'space-between\', marginBottom: 6 }}>\n        <span style={{ fontSize: 10, fontWeight: 900, letterSpacing: \'.12em\', color: \'var(--muted-foreground)\' }}>TIME {team}</span>\n        <span style={{ fontSize: 12, fontWeight: 900, color: \'var(--foreground)\' }}>Faixas</span>\n      </div>\n      {s.length === 0 ? <p style={{ margin: 0, fontSize: 11.5, opacity: 0.55 }}>defina as faixas</p> : s.map((t, i) => (\n        <p key={i} data-tier-line={`${team}-${i}`} style={{ margin: \'0 0 3px\', fontSize: 12.5, fontWeight: 800, color: \'var(--foreground)\', wordBreak: \'break-word\' }}>🎯 {fmtBRL(t.target)} <span style={{ color: \'var(--muted-foreground)\', fontWeight: 600 }}>→</span> 🎁 {t.prize}</p>\n      ))}\n    </div>\n  )\n}\n',
}
