BAK = '.bak-faixas'

def aplica(texto, edits):
    novo, msgs, ok = texto, [], True
    for tipo, marcador, antes, depois, desc in edits:
        if marcador in novo: msgs.append(f'  · já estava assim: {desc}'); continue
        if tipo == 'regex':
            ms = list(re.finditer(antes, novo)); n = len(ms)
            if n != 1: ok = False; msgs.append(f'  ✗ {desc}: o trecho esperado apareceu {n} vez(es) (precisa ser exatamente 1) — arquivo NÃO alterado'); continue
            m = ms[0]; rep = depois
            for i, gp in enumerate(m.groups(), 1): rep = rep.replace(f'@{i}@', gp)
            novo = novo[:m.start()] + rep + novo[m.end():]; msgs.append(f'  ✓ alterado: {desc}'); continue
        n = novo.count(antes)
        if n != 1: ok = False; msgs.append(f'  ✗ {desc}: o trecho esperado apareceu {n} vez(es) (precisa ser exatamente 1) — arquivo NÃO alterado'); continue
        novo = novo.replace(antes, depois); msgs.append(f'  ✓ alterado: {desc}')
    return novo, msgs, ok

def main(argv):
    args = [a for a in argv if not a.startswith('--')]; raiz = args[0] if args else '.'
    modo = 'desfazer' if '--desfazer' in argv else 'dry' if '--dry-run' in argv else 'aplicar'
    if not os.path.isdir(os.path.join(raiz, 'app')) or not os.path.isdir(os.path.join(raiz, 'lib')):
        print('Rode na RAIZ do projeto (onde ficam as pastas app/ e lib/), ex.: python aplicar-faixas-campanha.py .'); return 2
    print({'aplicar': 'APLICANDO', 'dry': 'SIMULAÇÃO (nada será gravado)', 'desfazer': 'DESFAZENDO'}[modo], '— Campanhas: faixas de valor\n')
    P = lambda rel: os.path.join(raiz, *rel.split('/'))
    falhas = 0
    if modo == 'desfazer':
        for rel in EDITS:
            p = P(rel)
            if os.path.isfile(p + BAK): os.replace(p + BAK, p); print(f'✔ {rel}\n  ✓ restaurado da cópia de segurança')
            else: print(f'✔ {rel}\n  · sem cópia de segurança: nada a desfazer')
        for rel, txt in NOVOS.items():
            p = P(rel)
            if os.path.isfile(p):
                if open(p, encoding='utf-8', newline='').read().replace('\r\n', '\n') == txt: os.remove(p); print(f'✔ {rel}\n  ✓ arquivo novo removido')
                else: print(f'✘ {rel}\n  ✗ foi alterado depois de criado: NÃO removi'); falhas += 1
        print('\nTudo certo.' if not falhas else f'\n{falhas} problema(s).'); return 1 if falhas else 0
    plano = []
    for rel, txt in NOVOS.items():
        p = P(rel)
        if os.path.isfile(p):
            if open(p, encoding='utf-8', newline='').read().replace('\r\n', '\n') == txt: print(f'✔ {rel}\n  · já estava assim (arquivo novo já criado)'); continue
            print(f'✘ {rel}\n  ✗ já existe e é DIFERENTE do esperado — NÃO alterado'); falhas += 1; continue
        print(f'✔ {rel}\n  ✓ criado (arquivo novo)'); plano.append(('novo', p, txt, None, None))
    for rel, edits in EDITS.items():
        p = P(rel)
        if not os.path.isfile(p): print(f'✘ {rel}\n  ✗ arquivo não encontrado'); falhas += 1; continue
        bruto = open(p, 'rb').read(); bom = bruto.startswith(b'\xef\xbb\xbf'); crlf = b'\r\n' in bruto
        texto = bruto.decode('utf-8-sig').replace('\r\n', '\n')
        novo, msgs, ok = aplica(texto, edits)
        print(('✔ ' if ok else '✘ ') + rel); print('\n'.join(msgs)); falhas += not ok
        if ok and novo != texto: plano.append(('edit', p, novo, bruto, (bom, crlf)))
    if modo == 'aplicar':
        for tipo, p, conteudo, bruto, fmt in plano:
            if tipo == 'novo': os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(conteudo.encode('utf-8')); continue
            if not os.path.isfile(p + BAK): open(p + BAK, 'wb').write(bruto)
            bom, crlf = fmt; saida = conteudo.replace('\n', '\r\n') if crlf else conteudo; dados = saida.encode('utf-8'); dados = (b'\xef\xbb\xbf' + dados) if bom else dados
            tmp = p + '.faixas.tmp'; open(tmp, 'wb').write(dados); os.replace(tmp, p)
    print('\nTudo certo.' if not falhas else f'\n{falhas} arquivo(s) com problema (os demais foram processados).')
    return 1 if falhas else 0

if __name__ == '__main__': sys.exit(main(sys.argv[1:]))
